const categories = [{ name: 'Books', icon: BookOpen, color: 'bg-orange-100 text-orange-700' }, { name: 'Electronics', icon: Laptop, color: 'bg-blue-100 text-blue-700' }, { name: 'Bikes', icon: Bike, color: 'bg-emerald-100 text-emerald-700' }, { name: 'Furniture', icon: Armchair, color: 'bg-purple-100 text-purple-700' }, { name: 'Clothing', icon: Shirt, color: 'bg-pink-100 text-pink-700' }, { name: 'Home essentials', icon: Armchair, color: 'bg-amber-100 text-amber-700' }, { name: 'Kids items', icon: Package, color: 'bg-cyan-100 text-cyan-700' }, { name: 'Kitchen', icon: ShoppingBag, color: 'bg-lime-100 text-lime-700' }, { name: 'Beauty', icon: Sparkles, color: 'bg-rose-100 text-rose-700' }]
